#include <stdio.h>
#include <stdlib.h>

#define INF 1000000000

typedef struct {
    int to;
    int next;
} Edge;

int head[300005];
Edge edges[600005];
int edge_cnt = 0;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

int order[300005];
int parent_node[300005];
int queue[300005];

void bfs(int n) {
    int front = 0, back = 0;
    queue[back++] = 1;
    parent_node[1] = 0;

    // Visited can be tracked by parent_node != 0 or 1 for root
    for (int i = 1; i <= n; i++) parent_node[i] = -1;
    parent_node[1] = 0;

    int idx = 0;
    while (front < back) {
        int u = queue[front++];
        order[idx++] = u;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (v != parent_node[u]) {
                parent_node[v] = u;
                queue[back++] = v;
            }
        }
    }
}

int max_uncov[300005];
int min_cent[300005];

int check(int R, int n, int K) {
    for (int i = 1; i <= n; i++) {
        max_uncov[i] = 0;
        min_cent[i] = INF;
    }

    int used = 0;

    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];

        if (max_uncov[u] + min_cent[u] <= R) {
            max_uncov[u] = -INF;
        }

        if (max_uncov[u] == R) {
            used++;
            min_cent[u] = 0;
            max_uncov[u] = -INF;
        }

        int p = parent_node[u];
        if (p != 0) {
            if (max_uncov[u] != -INF) {
                if (max_uncov[u] + 1 > max_uncov[p]) {
                    max_uncov[p] = max_uncov[u] + 1;
                }
            }
            if (min_cent[u] != INF) {
                if (min_cent[u] + 1 < min_cent[p]) {
                    min_cent[p] = min_cent[u] + 1;
                }
            }
        }
    }

    if (max_uncov[1] >= 0) {
        used++;
    }

    return used <= K;
}

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    for (int i = 0; i < n - 1; i++) {
        int u, v;
        if (scanf("%d %d", &u, &v) != 2) return 0;
        add_edge(u, v);
        add_edge(v, u);
    }

    bfs(n);

    int low = 0, high = n, ans = n;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (check(mid, n, k)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    printf("%d\n", ans);

    return 0;
}
